/**
 * Schema migrations, applied in order by `database.mjs` and tracked with
 * SQLite's `user_version`. Append; never edit a migration that has shipped.
 *
 * Ids are UUID text generated by the server. Timestamps are ISO-8601 UTC text,
 * which sorts correctly as a string. Booleans are 0/1.
 */

const NOW = "(strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))";

// One character of the room-code alphabet: no I, O, 0 or 1, which get misread
// when a code is read aloud.
const CODE_CHAR = "[A-HJ-NP-Z2-9]";

/** @type {readonly string[]} */
export const MIGRATIONS = [
  /* 1: everything, as it stood when the game moved off Supabase. */ `
create table rooms (
  id             text primary key,
  code           text not null check (code glob '${CODE_CHAR.repeat(6)}'),
  status         text not null default 'lobby'
                 check (status in ('lobby', 'in_game', 'finished')),
  host_player_id text references players(id) on delete set null,
  winning_score  integer not null default 10 check (winning_score between 1 and 50),
  created_at     text not null default ${NOW},
  last_active_at text not null default ${NOW}
);

-- A code is only reserved while the room is live; finished rooms release it.
create unique index rooms_code_live_uidx on rooms (code) where status <> 'finished';

create table players (
  id           text primary key,
  room_id      text not null references rooms(id) on delete cascade,
  display_name text not null check (length(trim(display_name)) between 1 and 24),
  team         text check (team in ('a', 'b')),
  is_host      integer not null default 0 check (is_host in (0, 1)),
  -- Append-only psychic rotation order.
  seat_order   integer not null,
  score        integer not null default 0 check (score >= 0),
  created_at   text not null default ${NOW},
  left_at      text
);

create index players_room_idx on players (room_id) where left_at is null;
create unique index players_seat_uidx
  on players (room_id, team, seat_order)
  where team is not null and left_at is null;

-- Only the SHA-256 of a session token is stored; the token itself lives in
-- the player's httpOnly cookie.
create table player_sessions (
  player_id    text primary key references players(id) on delete cascade,
  token_hash   blob not null unique,
  created_at   text not null default ${NOW},
  last_seen_at text not null default ${NOW}
);

-- Mirrors src/lib/game/deck.ts, which is synced in on every boot.
create table spectrum_cards (
  id          text primary key,
  left_label  text not null check (length(trim(left_label)) > 0),
  right_label text not null check (length(trim(right_label)) > 0),
  enabled     integer not null default 1 check (enabled in (0, 1))
);

create table games (
  id                 text primary key,
  room_id            text not null references rooms(id) on delete cascade,
  score_a            integer not null default 0 check (score_a >= 0),
  score_b            integer not null default 0 check (score_b >= 0),
  starting_team      text not null check (starting_team in ('a', 'b')),
  status             text not null default 'in_game'
                     check (status in ('lobby', 'in_game', 'finished')),
  winner             text check (winner in ('a', 'b')),
  sudden_death_index integer not null default 0 check (sudden_death_index >= 0),
  current_round_id   text references rounds(id) on delete set null,
  created_at         text not null default ${NOW},
  ended_at           text
);

create unique index games_room_active_uidx on games (room_id) where status = 'in_game';

-- Cards already drawn this game, so a spectrum never repeats.
create table game_used_cards (
  game_id text not null references games(id) on delete cascade,
  card_id text not null references spectrum_cards(id),
  primary key (game_id, card_id)
);

create table rounds (
  id                   text primary key,
  game_id              text not null references games(id) on delete cascade,
  room_id              text not null references rooms(id) on delete cascade,
  round_number         integer not null check (round_number > 0),
  active_team          text not null check (active_team in ('a', 'b')),
  psychic_player_id    text not null references players(id) on delete restrict,
  card_id              text not null references spectrum_cards(id),
  phase                text not null default 'clue'
                       check (phase in ('clue', 'guess', 'prediction', 'reveal', 'complete')),
  clue                 text check (clue is null or length(trim(clue)) between 1 and 120),
  clue_at              text,
  needle_controller_id text references players(id) on delete set null,
  needle_position      integer check (needle_position between 0 and 2000),
  prediction           text check (prediction in ('left', 'right')),
  -- Null until the reveal. Nothing about the target is in this row before
  -- then, so no query of rounds can leak it.
  revealed_target      integer check (revealed_target between 0 and 2000),
  active_points        integer check (active_points in (0, 2, 3, 4)),
  opponent_points      integer check (opponent_points in (0, 1)),
  revealed_at          text,
  -- sha256(nonce || target), published at creation so a client can check
  -- afterwards that the target never moved once the guesses were in.
  target_commitment    blob not null,
  created_at           text not null default ${NOW},

  constraint rounds_clue_present_after_clue_phase
    check (phase = 'clue' or clue is not null),
  constraint rounds_revealed_has_a_target
    check ((phase in ('reveal', 'complete')) = (revealed_target is not null))
);

create unique index rounds_game_number_uidx on rounds (game_id, round_number);
create index rounds_room_idx on rounds (room_id);

-- THE SECRET. Kept out of rounds, so that only code which names this table
-- explicitly can ever read it.
create table round_targets (
  round_id      text primary key references rounds(id) on delete cascade,
  target_center integer not null check (target_center between 0 and 2000),
  -- 16 random bytes, so the published commitment cannot be brute-forced even
  -- though the target has only ~1750 possible values.
  nonce         blob not null check (length(nonce) >= 16)
);

-- One committed needle per player per round.
create table round_guesses (
  round_id   text not null references rounds(id) on delete cascade,
  player_id  text not null references players(id) on delete cascade,
  position   integer not null check (position between 0 and 2000),
  points     integer check (points in (0, 2, 3, 4)),
  created_at text not null default ${NOW},
  primary key (round_id, player_id)
);

-- Votes to throw away the card in play. Keyed by card, so rerolling the card
-- makes every vote cast against the old one inert without deleting it.
create table round_skip_votes (
  round_id   text not null references rounds(id) on delete cascade,
  player_id  text not null references players(id) on delete cascade,
  card_id    text not null references spectrum_cards(id),
  created_at text not null default ${NOW},
  primary key (round_id, player_id, card_id)
);
`,
];
